const STORAGE_CUSTOM_PROGRAMS_KEY = "nexohub_housemix_programs_v2";
const STORAGE_CUSTOM_ESTUDIOS_KEY = "nexohub_housemix_estudios_v2";

// Normaliza nomes de emissoras/clientes para chaves canônicas (lidando com variações, slugs, IDs e typos)
export function normalizeClientKey(rawName?: any): string {
  if (!rawName) return "";
  let str = "";
  if (typeof rawName === "string") {
    str = rawName;
  } else if (typeof rawName === "object") {
    if (Array.isArray(rawName)) return "";
    str = rawName.nome || rawName.slug || rawName.nomeFantasia || rawName.razaoSocial || rawName.cliente || rawName.cliente_nome || "";
  } else {
    str = String(rawName);
  }
  if (!str) return "";

  let clean = str
    .toUpperCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();

  // 1. Interativa FM 94.9 (Goiânia - GO)
  // Observação crítica: a razão social da Interativa FM em Goiânia é "CULTURA FM STEREO SOM LTDA".
  // Portanto, "CULTURA FM STEREO SOM" pertence estritamente à Interativa FM, NUNCA à Cultura FM 97.3!
  if (
    clean === "B2F70324-D086-4A5D-A407-CBC4ACF98DCE" ||
    clean === "SUB_INTERATIVA_OPEC" ||
    clean.includes("INTERATIVAFM") ||
    clean.includes("INTERATIVA") ||
    clean.includes("INETRATIVA") ||
    clean.includes("CULTURA FM STEREO SOM")
  ) {
    return "INTERATIVA FM";
  }

  // 2. Cultura FM 97.3 (Santos - SP / A3 Produções e Marketing Ltda)
  if (
    clean === "66337743-4E4F-4950-B58F-750B0C76861E" ||
    clean.includes("CULTURAFM973") ||
    clean.includes("CULTURA973") ||
    clean.includes("A3 PRODUCOES") ||
    clean.includes("CULTURA FM 97") ||
    clean.includes("CULTURA 97") ||
    clean.includes("CULTURA")
  ) {
    return "CULTURA FM";
  }

  // 3. Positiva FM 99.1 (Goiânia - GO)
  if (
    clean === "D17E65AF-E407-466F-9B60-B55C43399513" ||
    clean === "SUB_POSITIVA_OPEC" ||
    clean.includes("POSITIVAFM") ||
    clean.includes("POSITIVA")
  ) {
    return "POSITIVA FM";
  }

  // 4. Jornal FM 96.5 (Inhumas - GO)
  if (
    clean === "48423CC6-F3B1-4BEA-8729-DD0AE76A89C3" ||
    clean.includes("JORNAL") ||
    clean.includes("TRANSMISSAO") ||
    clean.includes("INHUMAS")
  ) {
    return "JORNAL FM";
  }

  // 5. Nexo Brasil
  if (
    clean === "29B1107B-3EB0-4EB3-A7F8-D9CA93BE24B5" ||
    clean.includes("NEXO") ||
    clean.includes("ALEX")
  ) {
    return "NEXO BRASIL";
  }

  return clean;
}

